// ============================================================================
//  Salla orders  ->  Odoo import .xlsx  (two tabs, styled)
//  Body of the n8n "Build Odoo File" Code node. Runs once for all items.
//  Input  = rows from "Extract from File" (the raw Salla export).
//  Output = one item with the generated .xlsx in binary field `data`.
//  Requires the `exceljs` module (bundled in the Docker image,
//  allowed via NODE_FUNCTION_ALLOW_EXTERNAL=exceljs).
// ============================================================================
const ExcelJS = require('exceljs');

// ── CONFIG: Salla export column headers (exact, with fallbacks) ──────────────
const COLS = {
	orderRef: ['رقم الطلب', 'Order Reference', 'order_id', 'id'],
	name: ['اسم العميل', 'Complete Name', 'customer_name', 'name'],
	mobile: ['رقم الجوال', 'Mobile', 'mobile', 'phone'],
	city: ['المدينة', 'City', 'city'],
	street: ['عنوان العميل', 'Street', 'address'],
	payment: ['طريقة الدفع', 'Payment Method', 'payment'],
	shipping: ['تكلفة الشحن', 'shipping_cost', 'shipping'],
	skus: ['skus_json'],
	// Money columns used for the summary email only.
	cartTotal: ['مجموع السلة', 'Cart Total', 'subtotal'],
	vat: ['الضريبة', 'VAT', 'Tax', 'tax'],
	orderTotal: ['صافي المبيعات', 'إجمالي المبيعات', 'Total Sales', 'Net Sales'],
	refund: ['المبلغ المسترجع', 'Refunded Amount', 'refunded_amount'],
};

// skus_json item layout: [product_name, qty, sku_code, original_price, final_price]
const I_QTY = 1;
const I_SKU = 2;
const I_FINAL = 4;
// final_price is the LINE TOTAL -> unit price = final_price / qty.
const DIVIDE_PRICE_BY_QTY = true;

// Fixed values
const SALESPERSON = 'Legend Sleep Online';
const COUNTRY = 'Saudi Arabia';
const IS_A_COMPANY = false;
const ANALYTIC = '{"3": 100}';

// Styling (matches the reference file)
const BLUE = 'FF4472C4';
const RED = 'FFFF0000';
const WHITE = 'FFFFFFFF';

// ── DAILY INPUTS (from the upload form) ──────────────────────────────────────
const form = $('On form submission').first().json;
const seriesNumber = String(form['Series Number'] ?? '').trim();
const reportDate = String(form['Report Date'] ?? '').trim();
// Email-only inputs. Both optional: the period falls back to the report date.
const recipientName = String(form['Recipient Name'] ?? '').trim() || 'Sir/Madam';
const period = String(form['Order Period'] ?? '').trim() || reportDate;

// Signature on the summary email. Edit here, not in the Send Email node.
const SENDER = {
	name: 'Muhammad Uzair Yusufi',
	title: 'Ecommerce Assistant Manager',
	phone: '+966545169303',
	email: 'muhammad.uzair@legendsleepsa.com',
	address: 'Street 63, 2nd Industrial City, Jeddah, 22756',
};

// ── HELPERS ──────────────────────────────────────────────────────────────────
function pick(row, candidates) {
	for (const c of candidates) {
		if (row[c] !== undefined && row[c] !== null && String(row[c]).trim() !== '') return row[c];
	}
	const keys = Object.keys(row);
	for (const c of candidates) {
		const k = keys.find((kk) => kk.trim().toLowerCase() === c.trim().toLowerCase());
		if (k && row[k] !== undefined && row[k] !== null && String(row[k]).trim() !== '') return row[k];
	}
	return undefined;
}

function hasCol(row, candidates) {
	const keys = Object.keys(row).map((k) => k.trim().toLowerCase());
	return candidates.some((c) => keys.includes(c.trim().toLowerCase()));
}

function num(v) {
	if (v === undefined || v === null) return 0;
	const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
	return isNaN(n) ? 0 : n;
}

function round2(n) {
	return Math.round((n + Number.EPSILON) * 100) / 100;
}

function paymentPrefix(p) {
	const s = String(p ?? '').trim();
	const low = s.toLowerCase();
	if (s.includes('مدى') || low.includes('mada')) return 'Mada/Span';
	if (s.includes('تابي') || low.includes('tabby')) return 'Tabby';
	if (s.includes('ئتمان') || low.includes('credit')) return 'Credit Card';
	if (s.includes('تمارا') || low.includes('tamara')) return 'Tamara';
	if (s.includes('إمكان') || s.includes('امكان') || low.includes('emkan')) return 'Emkan';
	if (low.includes('apple')) return 'Mada/Span';
	if (low.includes('mispay')) return 'MisPAY';
	// STC came through bare before, so it never picked up the suffix
	if (low.includes('stc') || s.includes('اس تي سي') || s.includes('إس تي سي')) return 'STC';
	return s; // unknown -> pass through with the suffix
}

function mapPayment(p) {
	const prefix = paymentPrefix(p);
	return prefix ? `${prefix}- Legend Sleep E-commerce` : '';
}

// Warehouse names as Odoo expects them. JEDDAH is the default for every city
// that is neither Riyadh nor one of the Eastern Province cities listed in
// DAMMAM_CITIES below, and the summary email says so explicitly.
const WH_RIYADH = 'RIYADH-WAREHOUSE';
const WH_DAMMAM = 'DAMMAM-WAREHOUSE';
const WH_JEDDAH = 'BEDDING FACTORY-WAREHOUSE';

// Every city served out of Dammam. Written the way a human would spell them --
// they get normalised below, so case, hyphens, spaces and the "Al " prefix all
// stop mattering ("Al Khobar" / "AL KHOBAR" / "Al-Khobar" / "alkhobar" all match).
// Add a new city by adding a spelling here; nothing else needs to change.
const DAMMAM_CITIES = [
	'Dammam', 'Ad Dammam', 'الدمام',
	'Al Khobar', 'Khobar', 'الخبر',
	'Dhahran', 'Al Dhahran', 'الظهران',
	'Saihat', 'Sayhat', 'سيهات',
	'Anak', 'عنك',
	'Al Qatif', 'Qatif', 'القطيف',
	'Tarout', 'Tarut', 'Taroot', 'تاروت',
	'Safwa', 'Al Safwa', 'صفوى',
	'Ras Tanura', 'Ras Tanurah', 'Ras Tannurah', 'رأس تنورة',
	'Al Jubail', 'Jubail', 'Jubayl', 'الجبيل',
	'Abqaiq', 'Buqayq', 'بقيق',
	'Al Hufuf', 'Hufuf', 'Al Hofuf', 'Hofuf', 'الهفوف',
	'Al Oyun', 'Oyun', 'Al Uyun', 'Uyun', 'العيون',
	'Al Mubarraz', 'Mubarraz', 'Al Mubaraz', 'Mubaraz', 'المبرز',
	'Al Ahsa', 'Ahsa', 'Al Hasa', 'Hasa', 'الأحساء',
];

// Collapse a city name so spelling noise cannot cause a miss: lowercase, fold
// Arabic alef/ya/ta-marbuta variants, drop diacritics, then strip everything
// that is not a letter or digit (spaces, hyphens, punctuation).
function normCity(value) {
	return String(value ?? '')
		.toLowerCase()
		.replace(/[\u064B-\u0652\u0640]/g, '')
		.replace(/[أإآٱ]/g, 'ا')
		.replace(/ى/g, 'ي')
		.replace(/ة/g, 'ه')
		.replace(/[^a-z0-9\u0621-\u064A]/g, '');
}

const DAMMAM_KEYS = DAMMAM_CITIES.map(normCity).filter(Boolean);

// Exact match always counts. Substring matching is only allowed for keys of 5+
// characters, so a short name like "Anak" cannot fire inside an unrelated city,
// while "Jubail Industrial City" still resolves to Jubail.
function isDammamCity(city) {
	const c = normCity(city);
	if (!c) return false;
	return DAMMAM_KEYS.some((key) => c === key || (key.length >= 5 && c.includes(key)));
}

function mapWarehouse(city) {
	const s = String(city ?? '').trim().toLowerCase();
	if (s.includes('riyadh') || s.includes('الرياض')) return WH_RIYADH;
	if (isDammamCity(city)) return WH_DAMMAM;
	return WH_JEDDAH;
}

function isInvalidSku(sku) {
	const s = String(sku ?? '').trim().toLowerCase();
	return s === '' || s === '0' || s === 'null' || s === 'undefined' || s === 'false';
}

function parseSkus(val) {
	if (val === undefined || val === null || val === '') return [];
	if (Array.isArray(val)) return val;
	try {
		const parsed = JSON.parse(val);
		return Array.isArray(parsed) ? parsed : [];
	} catch (e) {
		return [];
	}
}

// ── READ INPUT ───────────────────────────────────────────────────────────────
// Rows come from the "Extract from File" node (it reads the uploaded .xlsx into
// header-keyed JSON items). This is n8n's own reader — robust across versions.
const rows = $input.all().map((i) => i.json);

if (rows.length === 0) {
	throw new Error('No rows received. Is the "Extract from File" node connected before this one?');
}
if (!hasCol(rows[0], COLS.skus)) {
	throw new Error(
		'Could not find the "skus_json" column. Available columns: ' + Object.keys(rows[0]).join(' | '),
	);
}

// ── TRANSFORM ────────────────────────────────────────────────────────────────
const customers = [];
const orderRows = [];
// Orders that are NOT going to the Jeddah default, listed in the summary email.
const warehouseChanges = [];

for (const row of rows) {
	const orderRef = pick(row, COLS.orderRef) ?? null;
	const rawName = String(pick(row, COLS.name) ?? '').trim();
	const custName = `${rawName}${seriesNumber}`;
	const mobile = pick(row, COLS.mobile) ?? '';
	const city = pick(row, COLS.city) ?? '';
	const street = pick(row, COLS.street) ?? '';
	const paymentTerm = mapPayment(pick(row, COLS.payment));
	const warehouse = mapWarehouse(city);
	if (warehouse !== WH_JEDDAH && orderRef !== null && orderRef !== undefined) {
		warehouseChanges.push({ orderRef: String(orderRef), warehouse });
	}
	const shipping = num(pick(row, COLS.shipping));
	let items = parseSkus(pick(row, COLS.skus));

	customers.push({
		'Complete Name': custName,
		Phone: mobile,
		City: city,
		Street: street,
		Country: COUNTRY,
		'Is a Company': IS_A_COMPANY,
	});

	if (items.length === 0) items = [['', 1, '', 0, 0]];

	const firstIdx = orderRows.length;
	let orderHasInvalidSku = false;
	let first = true;

	for (const item of items) {
		const qty = num(item[I_QTY]) || 1;
		const sku = item[I_SKU];
		const finalPrice = num(item[I_FINAL]);
		const unitPrice = round2(DIVIDE_PRICE_BY_QTY && qty ? finalPrice / qty : finalPrice);
		const invalid = isInvalidSku(sku);
		if (invalid) orderHasInvalidSku = true;

		orderRows.push({
			orderRef: first ? orderRef : null,
			product: invalid ? 'NO SKU' : String(sku),
			unitPrice,
			qty,
			customer: first ? custName : null,
			salesperson: first ? SALESPERSON : null,
			paymentTerms: first ? paymentTerm : null,
			warehouse: first ? warehouse : null,
			analytic: ANALYTIC,
			productRed: invalid,
			orderRefRed: false,
		});
		first = false;
	}

	if (orderHasInvalidSku) orderRows[firstIdx].orderRefRed = true;

	if (shipping > 0) {
		orderRows.push({
			orderRef: null,
			product: 'Delivery_007',
			unitPrice: round2(shipping),
			qty: 1,
			customer: null,
			salesperson: null,
			paymentTerms: null,
			warehouse: null,
			analytic: ANALYTIC,
			productRed: false,
			orderRefRed: false,
		});
	}
}

// ── BUILD STYLED WORKBOOK ────────────────────────────────────────────────────
// IMPORTANT: assign each cell value explicitly via getCell().value. ExcelJS's
// addRow([...]) array form does NOT persist values inside n8n's Code-node
// sandbox (the written file comes out with empty rows), so we avoid it.
function writeRow(ws, rowIdx, values) {
	const row = ws.getRow(rowIdx);
	for (let i = 0; i < values.length; i++) {
		const v = values[i];
		row.getCell(i + 1).value = v === undefined ? null : v;
	}
	return row;
}

function styleHeader(rowObj, count) {
	for (let i = 1; i <= count; i++) {
		const cell = rowObj.getCell(i);
		cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: BLUE } };
		cell.font = { color: { argb: WHITE }, bold: true };
	}
}

function redCell(cell) {
	cell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: RED } };
	cell.font = { color: { argb: WHITE }, bold: true };
}

const wb = new ExcelJS.Workbook();

// Tab 1 — Customer Data
const ws1 = wb.addWorksheet('Customer Data');
const custHeaders = ['Complete Name', 'Phone', 'City', 'Street', 'Country', 'Is a Company'];
writeRow(ws1, 1, custHeaders);
styleHeader(ws1.getRow(1), custHeaders.length);
customers.forEach((c, idx) => writeRow(ws1, idx + 2, custHeaders.map((h) => c[h])));

// Tab 2 — Order Data
const ws2 = wb.addWorksheet('Order Data');
const orderHeaders = [
	'Order Reference',
	'Order Lines/Product/Name',
	'Unit Price',
	'Qty',
	'Customer',
	'Salesperson',
	'Payment Terms',
	'Warehouse',
	'order_line/analytic_distribution',
];
writeRow(ws2, 1, orderHeaders);
styleHeader(ws2.getRow(1), orderHeaders.length);
orderRows.forEach((r, idx) => {
	const row = writeRow(ws2, idx + 2, [
		r.orderRef,
		r.product,
		r.unitPrice,
		r.qty,
		r.customer,
		r.salesperson,
		r.paymentTerms,
		r.warehouse,
		r.analytic,
	]);
	if (r.orderRefRed) redCell(row.getCell(1));
	if (r.productRed) redCell(row.getCell(2));
});

for (let i = 1; i <= custHeaders.length; i++) ws1.getColumn(i).width = 24;
for (let i = 1; i <= orderHeaders.length; i++) ws2.getColumn(i).width = 24;

// ── SUMMARY FIGURES ──────────────────────────────────────────────────────────
// The prices inside skus_json are PRE-VAT. So unit price x quantity, plus
// shipping, is the w/o-VAT subtotal -- not the with-VAT total. Salla ships the
// VAT in its own column, and subtotal + that column equals the export's own
// order total to the cent. Verified on 15th Aug - 59579.xlsx:
//     50,690.86 lines + 1,117.39 shipping = 51,808.25 w/o VAT
//                        + 7,771.27 VAT  = 59,579.52 with VAT  (= صافي المبيعات)
// Prefer the real VAT column over multiplying by 1.15: Salla rounds VAT per
// order, so x1.15 would give 59,579.49 and drift further on bigger days.
const VAT_RATE = 0.15;
const sumCol = (candidates) => rows.reduce((s, row) => s + num(pick(row, candidates)), 0);

// what we actually wrote into the sheet, so the email always matches the file
const totalWithoutVat = round2(orderRows.reduce((s, r) => s + r.unitPrice * r.qty, 0));

const vatFromExport = round2(sumCol(COLS.vat));
const orderTotalFromExport = round2(sumCol(COLS.orderTotal));
const totalWithVat =
	orderTotalFromExport > 0
		? orderTotalFromExport
		: vatFromExport > 0
			? round2(totalWithoutVat + vatFromExport)
			: round2(totalWithoutVat * (1 + VAT_RATE));

// Returns come straight from the refund column; it is what was paid back, so
// it already includes VAT.
const returnWithVat = round2(sumCol(COLS.refund));
const returnWithoutVat = returnWithVat > 0 ? round2(returnWithVat / (1 + VAT_RATE)) : 0;

// Cross-check: the cart-total column should equal the sum of the skus_json
// lines. If it does not, the export and the sheet disagree and someone should
// look before uploading to Odoo.
const cartFromExport = round2(sumCol(COLS.cartTotal));
const linesOnly = round2(orderRows.reduce((s, r) => s + (r.product === 'Delivery_007' ? 0 : r.unitPrice * r.qty), 0));
const cartMismatch = cartFromExport > 0 && Math.abs(cartFromExport - linesOnly) > 0.05
	? `Cart total in the export is ${cartFromExport} but the order lines add up to ${linesOnly}.`
	: '';

const money = (n) => n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

// ── SUMMARY EMAIL ────────────────────────────────────────────────────────────
const MAIL_YELLOW = '#ffff00';
const MAIL_NAVY = '#1f3864';
const MAIL_RED = '#ff0000';
const mailCell = 'border:1px solid #000;padding:6px 14px;text-align:center;font-size:14px';

const amountTable = (withVat, withoutVat) => `
<table style="border-collapse:collapse;margin:6px 0 18px">
	<tr>
		<td style="${mailCell};background:${MAIL_YELLOW};font-weight:bold">with VAT</td>
		<td style="${mailCell};background:${MAIL_YELLOW};font-weight:bold">w/o VAT</td>
	</tr>
	<tr>
		<td style="${mailCell}">${withVat}</td>
		<td style="${mailCell}">${withoutVat}</td>
	</tr>
</table>`;

const warehouseTable = warehouseChanges.length
	? `
<table style="border-collapse:collapse;margin:6px 0 18px">
	<tr>
		<td style="${mailCell};background:${MAIL_NAVY};color:#fff;font-weight:bold;min-width:230px">Order Reference</td>
		<td style="${mailCell};background:${MAIL_NAVY};color:#fff;font-weight:bold;min-width:230px">Warehouse</td>
	</tr>
	${warehouseChanges
		.map((w) => `<tr><td style="${mailCell}">${w.orderRef}</td><td style="${mailCell}">${w.warehouse}</td></tr>`)
		.join('')}
</table>`
	: `<p style="font-size:14px">All orders are set for the Jeddah warehouse &quot;${WH_JEDDAH}&quot;.</p>`;

const emailHtml = `
<div style="font-family:Calibri,Arial,sans-serif;color:#000;font-size:14px;line-height:1.5">
<p>Dear ${recipientName},</p>

<p>Please find below the Salla&ndash;Odoo order data for ${period}.</p>

<p style="font-weight:bold;margin-bottom:2px">Total Amount of Today Orders:</p>
${amountTable(money(totalWithVat), money(totalWithoutVat))}

<p style="font-weight:bold;margin-bottom:2px">Total Amount of Return Orders:</p>
${
	returnWithVat > 0
		? amountTable(money(returnWithVat), money(returnWithoutVat))
		: amountTable('&#8212;&#8212;&#8212;', '&#8212;&#8212;&#8212;')
}

${cartMismatch ? `<p style="margin:0 0 12px"><span style="background:${MAIL_RED};color:#fff;font-weight:bold">Check: ${cartMismatch}</span></p>` : ''}
<p style="margin:0"><span style="background:${MAIL_YELLOW};font-weight:bold">Kindly NOTE:</span></p>
<p style="margin:2px 0 18px"><span style="background:${MAIL_RED};color:#000;font-weight:bold">Let me know if you find any errors</span></p>

<p style="margin:0"><span style="background:${MAIL_YELLOW};font-weight:bold">Warehouse changed of below orders</span></p>
<p style="margin:2px 0 6px"><span style="background:${MAIL_YELLOW};font-weight:bold">Rest all orders are set for Jeddah Warehouse &quot;${WH_JEDDAH}&quot;</span></p>
${warehouseTable}

<p>I have also attached the order sheet for your reference.</p>

<p style="font-weight:bold;margin-bottom:2px">File details:</p>
<ul style="margin-top:2px">
	<li>Tab 1 (Customer Data): Customer information and related details</li>
	<li>Tab 2 (Order Data): Order-level data required for processing and upload</li>
</ul>

<p>In case you encounter any missing fields, mismatches, or upload issues, kindly share the details immediately so we can address them without delay.</p>

<p>Kind regards,</p>

<p style="margin:0"><b>${SENDER.name}</b><br>
${SENDER.title}<br>
M: <a href="tel:${SENDER.phone.replace(/[^0-9+]/g, '')}">${SENDER.phone}</a><br>
E: <a href="mailto:${SENDER.email}">${SENDER.email}</a><br>
A: ${SENDER.address}</p>
</div>`;

// ── OUTPUT ───────────────────────────────────────────────────────────────────
const fileName = `${reportDate || 'salla'} salla-odoo.xlsx`;
const buffer = await wb.xlsx.writeBuffer();
const binary = await this.helpers.prepareBinaryData(
	Buffer.from(buffer),
	fileName,
	'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
);

return [
	{
		json: {
			orders: customers.length,
			orderLines: orderRows.length,
			fileName,
			totalWithVat,
			totalWithoutVat,
			returnWithVat,
			returnWithoutVat,
			vatFromExport,
			orderTotalFromExport,
			cartMismatch,
			warehouseChanges,
			period,
			emailHtml,
		},
		binary: { data: binary },
	},
];
